const body = $input.first().json.body || $input.first().json;
const MODALIDADES = { pregao_eletronico: 6, dispensa: 8 };

// aceita tanto array de verdade (chamada direta/teste) quanto string separada por
// virgula (a tool do Orquestrador manda assim -- o mecanismo de placeholder do
// HTTP Request Tool preenche texto simples, nao array JSON).
function paraLista(valorArray, valorCsv) {
  if (Array.isArray(valorArray) && valorArray.length) return valorArray.map(String).filter(Boolean);
  if (typeof valorCsv === 'string' && valorCsv.trim()) return valorCsv.split(',').map(s => s.trim()).filter(Boolean);
  return [];
}
function paraNumero(valor) {
  // cobre tanto numero de verdade (chamada direta/teste) quanto texto vindo do
  // placeholder da tool (numerico ou string vazia quando o usuario nao especificou)
  if (valor == null || valor === '') return null;
  const n = Number(valor);
  return isNaN(n) ? null : n;
}

const modalidadesLista = paraLista(body.modalidades, body.modalidades_csv);
const modalidadesPedidas = modalidadesLista.length ? modalidadesLista : ['pregao_eletronico', 'dispensa'];

const hoje = new Date();
const ontem = new Date(hoje.getTime() - 24 * 60 * 60 * 1000);
const fmt = (d) => d.toISOString().slice(0, 10).replace(/-/g, '');

const palavras = paraLista(body.palavras_chave, body.palavras_chave_csv);
const uf = paraLista(body.uf, body.uf_csv);
const valor_min = paraNumero(body.valor_min);
const valor_max = paraNumero(body.valor_max);

const out = [];
for (const m of modalidadesPedidas) {
  const codigo = MODALIDADES[m];
  if (!codigo) continue;
  out.push({ json: { palavras, uf, valor_min, valor_max, modalidade_codigo: codigo, dataInicial: fmt(ontem), dataFinal: fmt(hoje) } });
}
return out;

const consulta = $('Loop Consultas Livre').first().json;
const resp = $input.first().json;
const registrosPagina1 = (resp && resp.data) || [];
const totalPaginas = (resp && resp.totalPaginas) || 1;
const paginasFaltando = [];
for (let p = 2; p <= Math.min(totalPaginas, 60); p++) paginasFaltando.push(p);
return [{ json: { consulta, registrosPagina1, paginasFaltando } }];

const base = $('Calcular Paginacao Livre').first().json;
const extras = $input.all().map(i => (i.json && i.json.data) || []).flat();
return [{ json: { ...base.consulta, data: base.registrosPagina1.concat(extras) } }];

function normalizar(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
const combinados = $input.all();
const resultados = [];
for (const item of combinados) {
  const consulta = item.json;
  const registros = consulta.data || [];
  const palavrasNorm = (consulta.palavras || []).map(normalizar).filter(Boolean);
  const ufsPedido = consulta.uf || [];
  for (const r of registros) {
    const objetoNorm = normalizar(r.objetoCompra);
    if (palavrasNorm.length && !palavrasNorm.some(p => objetoNorm.includes(p))) continue;
    const valor = r.valorTotalEstimado != null ? Number(r.valorTotalEstimado) : null;
    if (consulta.valor_min != null && (valor == null || valor < consulta.valor_min)) continue;
    if (consulta.valor_max != null && (valor == null || valor > consulta.valor_max)) continue;
    const uf = r.unidadeOrgao ? r.unidadeOrgao.ufSigla : null;
    if (ufsPedido.length && !ufsPedido.includes(uf)) continue;
    const cnpj = (r.orgaoEntidade && r.orgaoEntidade.cnpj) || (r.orgaoSubRogado && r.orgaoSubRogado.cnpj) || '';
    resultados.push({
      pncp_id: r.numeroControlePNCP,
      objeto: r.objetoCompra,
      orgao: (r.orgaoEntidade && r.orgaoEntidade.razaoSocial) || '',
      valor, uf,
      municipio: r.unidadeOrgao ? r.unidadeOrgao.municipioNome : null,
      modalidade_nome: r.modalidadeNome,
      link: 'https://pncp.gov.br/app/editais/' + cnpj + '/' + r.anoCompra + '/' + r.sequencialCompra
    });
  }
}
// teto de resultados devolvidos pro agente (evita resposta gigante numa conversa)
return [{ json: { total_encontrado: resultados.length, resultados: resultados.slice(0, 20) } }];
